     7→use protocol::error;
     8→use protocol::app::{AdminCap, ProtocolApp};
     9→use protocol::market::Market;
    10→use protocol::interest::InterestModel;
    11→use protocol::asset::AssetConfig;
    12→
    13→const ASSET_MARKET_CONFIG: u8 = 0;
    14→const ASSET_INTEREST_MODEL: u8 = 1;
    15→const ASSET_BORROW_PAUSE_STATE: u8 = 2;
    16→// fource more fields reserved, 3 - 6
    17→
    18→const DECIMAL_DENOMINATOR: u64 = 10000;
    19→const PRICISE_DECIMAL_DENOMINATOR: u64 = 1000000000000000000;
    20→
    21→public struct AssetOnboardedEvent has copy, drop {
    22→    market: TypeName,
    23→    interest_model: InterestModel,
    24→    asset_config: AssetConfig,
    25→    time: u64,
    26→    operator: address,
    27→}
    28→
    29→public struct AssetUpdated<T> has copy, drop {
    30→    what: u8,
    31→    market: TypeName,
    32→    asset: TypeName,
    33→    new: T
    34→}
    35→
    36→public fun onboard_new_asset<MarketType, CoinType>(
    37→    _: &AdminCap,
    38→    self: &ProtocolApp,
    39→    market: &mut Market<MarketType>,
    40→    interest_model: InterestModel,
    41→    asset_config: AssetConfig,
    42→    clock: &Clock,
    43→    ctx: &mut TxContext,
    44→) {
    45→    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());
    46→
    47→    self.validate_market<MarketType>(market);
    48→    self.ensure_version_matches();
    49→
    50→    let now = clock.timestamp_ms() / 1000;
    51→    market.onboard_new_asset<MarketType, CoinType>(
    52→        interest_model,
    53→        asset_config,
    54→        now,
    55→        ctx,
    56→    );
    57→
    58→
    59→    emit(AssetOnboardedEvent {
    60→        market: std::type_name::with_defining_ids<MarketType>(),
    61→        interest_model,
    62→        asset_config,
    63→        time: now,
    64→        operator: ctx.sender(),
    65→    });
    66→}
    67→
    68→/// Create a asset configuration
    69→public fun create_market_asset_config(
    70→    _: &AdminCap,
    71→    self: &ProtocolApp,
    72→    min_borrow_amount: u64,
    73→    max_borrow_amount: u64,
    74→    max_deposit_amount: u64,
    75→    repay_fee_rate: u64, // basis points
    76→    liquidation_fee_rate: u64, // basis points
    77→): AssetConfig {
    78→    // Validate parameters
    79→    assert!(min_borrow_amount > 0, error::invalid_params_error());
    80→    assert!(liquidation_fee_rate <= DECIMAL_DENOMINATOR, error::invalid_params_error());
    81→    assert!(repay_fee_rate <= DECIMAL_DENOMINATOR, error::invalid_params_error());
    82→
    83→    self.ensure_version_matches();
    84→
    85→    let liquidation_fee = math::float::from_quotient(liquidation_fee_rate, DECIMAL_DENOMINATOR);
    86→    let repay_fee = math::float::from_quotient(repay_fee_rate, DECIMAL_DENOMINATOR);
    87→
    88→    protocol::asset::new_asset_config(
    89→        min_borrow_amount,
    90→        max_borrow_amount,
    91→        repay_fee,
    92→        max_deposit_amount,
    93→        liquidation_fee
    94→    )
    95→}
    96→
    97→/// Update borrow configuration for an asset
    98→public fun update_market_asset_config<MarketType, CoinType>(
    99→    _: &AdminCap,
   100→    self: &ProtocolApp,
   101→    market: &mut Market<MarketType>,
   102→    asset_config: AssetConfig,
   103→) {
   104→    self.validate_market<MarketType>(market);
   105→    self.ensure_version_matches();
   106→
   107→    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());
   108→
   109→    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
   110→    asset.update_asset_config<MarketType>(asset_config);
   111→
   112→    emit(AssetUpdated<AssetConfig>{
   113→        what: ASSET_MARKET_CONFIG,
   114→        market: std::type_name::with_defining_ids<MarketType>(),
   115→        asset: std::type_name::with_defining_ids<CoinType>(),
   116→        new: asset_config
   117→    });
   118→}
   119→
   120→public fun update_market_asset_interest_model<MarketType, CoinType>(
   121→    _: &AdminCap,
   122→    self: &ProtocolApp,
   123→    market: &mut Market<MarketType>,
   124→    interest_model: InterestModel,
   125→) {
   126→    self.validate_market<MarketType>(market);
   127→    self.ensure_version_matches();
   128→
   129→    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());
   130→
   131→    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
   132→    asset.update_interest_model<MarketType>(interest_model);
   133→
   134→    emit(AssetUpdated<InterestModel>{
   135→        what: ASSET_INTEREST_MODEL,
   136→        market: std::type_name::with_defining_ids<MarketType>(),
   137→        asset: std::type_name::with_defining_ids<CoinType>(),
   138→        new: interest_model
   139→    });
   140→}
   141→
   142→public fun update_asset_paused_state<MarketType, CoinType>(
   143→    _: &AdminCap,
   144→    self: &ProtocolApp,
   145→    market: &mut Market<MarketType>,
   146→    what: u8,
   147→    is_paused: bool
   148→) {
   149→    self.validate_market<MarketType>(market);
   150→    self.ensure_version_matches();
   151→
   152→    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());
   153→
   154→    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
   155→    asset.change_operation_status<MarketType>(what, is_paused);
   156→
   157→    emit(AssetUpdated<bool>{
   158→        what: ASSET_BORROW_PAUSE_STATE + what,
   159→        market: std::type_name::with_defining_ids<MarketType>(),
   160→        asset: std::type_name::with_defining_ids<CoinType>(),
   161→        new: is_paused,
   162→    });
   163→}
   164→
   165→/// Create an interest model
   166→public fun create_interest_model(
   167→    admin_cap: &AdminCap,
   168→    self: &ProtocolApp,
   169→    base_rate_per_sec: u64,
   170→    borrow_rate_on_mid_kink: u64,
   171→    mid_kink: u64,
   172→    borrow_rate_on_high_kink: u64,
   173→    high_kink: u64,
   174→    max_borrow_rate: u64,
   175→): InterestModel {
   176→    assert!(mid_kink > 0, error::invalid_params_error());
   177→    assert!(mid_kink < high_kink && high_kink < DECIMAL_DENOMINATOR, error::invalid_params_error());
   178→    assert!(base_rate_per_sec <= borrow_rate_on_mid_kink, error::invalid_params_error());
   179→    assert!(borrow_rate_on_mid_kink <= borrow_rate_on_high_kink && borrow_rate_on_high_kink <= max_borrow_rate, error::invalid_params_error());
   180→
   181→    self.ensure_version_matches();
   182→
   183→    create_interest_model_inner(admin_cap, base_rate_per_sec, borrow_rate_on_mid_kink, mid_kink, borrow_rate_on_high_kink, high_kink, max_borrow_rate)
   184→}
   185→
   186→fun create_interest_model_inner(
   187→    _: &AdminCap,
   188→    base_rate_per_sec: u64,
   189→    borrow_rate_on_mid_kink: u64,
   190→    mid_kink: u64,
   191→    borrow_rate_on_high_kink: u64,
   192→    high_kink: u64,
   193→    max_borrow_rate: u64,
   194→): InterestModel {
   195→    // Convert u64 values to UQ64_64 for the interest model
   196→    let base_rate = math::float::from_quotient(base_rate_per_sec, PRICISE_DECIMAL_DENOMINATOR);
   197→    let mid_kink_rate = math::float::from_quotient(
   198→        borrow_rate_on_mid_kink,
   199→        PRICISE_DECIMAL_DENOMINATOR,
   200→    );
   201→    let mid_kink_util = math::float::from_quotient(mid_kink, DECIMAL_DENOMINATOR);
